<?php
require __DIR__.'/../timeguard_api/config/rules.php';
$count=0;function check(bool $v,string $name): void {global $count;if(!$v){throw new RuntimeException($name);}echo "PASS $name\n";$count++;}
$p=[['lat'=>0,'lng'=>0],['lat'=>0,'lng'=>2],['lat'=>1,'lng'=>2],['lat'=>1,'lng'=>1],['lat'=>2,'lng'=>1],['lat'=>2,'lng'=>0]];
check(polygon_valid($p),'valid concave polygon');check(point_in_polygon(.5,1.5,$p),'inside');check(!point_in_polygon(1.5,1.5,$p),'concave exclusion');check(point_in_polygon(1,1,$p),'vertex included');check(point_in_polygon(0,1,$p),'edge included');check(point_in_polygon(.5,1.5,array_reverse($p)),'reverse winding');check(!point_in_polygon(-.1,.5,$p),'outside');check(!polygon_valid([['lat'=>0,'lng'=>0],['lat'=>1,'lng'=>1],['lat'=>0,'lng'=>1],['lat'=>1,'lng'=>0]]),'self crossing rejected');check(!polygon_valid([['lat'=>0,'lng'=>0],['lat'=>1,'lng'=>1],['lat'=>2,'lng'=>2]]),'zero area rejected');check(!polygon_valid([['lat'=>91,'lng'=>0],['lat'=>1,'lng'=>1],['lat'=>2,'lng'=>2]]),'latitude range');
$a=['status'=>'active','effective_date'=>'2026-09-01','end_date'=>'2026-09-17'];check(assignment_valid($a,'2026-09-17'),'inclusive end');check(!assignment_valid($a,'2026-09-18'),'expired assignment');check(!assignment_valid($a,'2026-08-31'),'future assignment');check(!assignment_valid(array_replace($a,['status'=>'inactive']),'2026-09-17'),'inactive assignment');
check(transition_error([],true)!==null,'out requires in');check(transition_error([],false)===null,'first in');check(transition_error([['check_type'=>'เข้างาน']],false)!==null,'duplicate in');check(transition_error([['check_type'=>'เข้างาน']],true)===null,'valid out');check(transition_error([['check_type'=>'เข้างาน'],['check_type'=>'ออกงาน']],true)!==null,'duplicate out');echo "SUCCESS $count rules\n";
